contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint fundAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (fundAmount)); require(fundAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= fundAmount);
        require(c.Owner() == address(this));

        c.Command{value: fundAmount}(address(this), ""); if (__ESBMC_reverted()) return;

        uint beforeTestBalance = address(this).balance;
        uint beforeContractBalance = address(c).balance;

        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterContractBalance = address(c).balance;
        uint afterTestBalance = address(this).balance;

        assert(!reverted && afterContractBalance == 0 && afterTestBalance == beforeTestBalance + beforeContractBalance);
    }
}

