// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MultiplicatorX4 c;

    function setUp() public {
        c = new MultiplicatorX4();
    }

    function _run(uint256 fundAmount) internal {
        fundAmount = bound(fundAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= fundAmount);
        vm.assume(c.Owner() == address(this));
        try c.Command{value: fundAmount}(address(this), "") {} catch { return; }
        uint beforeTestBalance = address(this).balance;
        uint beforeContractBalance = address(c).balance;
        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint afterContractBalance = address(c).balance;
        uint afterTestBalance = address(this).balance;
        assertTrue(!reverted && afterContractBalance == 0 && afterTestBalance == beforeTestBalance + beforeContractBalance);
    }

    function testFuzz_run(uint256 fundAmount) public {
        _run(fundAmount);
    }

    receive() external payable {}
}
